<?php require 'header.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$product=$s->fetch();if(!$product){flash('error','Product not found.');header('Location: manage-products.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$s=db()->prepare('UPDATE products SET name=?,brand=?,category_id=?,price=?,storage=?,`condition`=?,quality=?,stock=?,description=?,specifications=? WHERE id=?');$s->execute([trim($_POST['name']),$_POST['brand'],$_POST['category_id'],$_POST['price'],trim($_POST['storage']),$_POST['condition'],trim($_POST['quality']),$_POST['stock'],trim($_POST['description']),trim($_POST['specifications']),$id]);db()->prepare('DELETE FROM product_colors WHERE product_id=?')->execute([$id]);foreach(array_filter(array_map('trim',explode(',',$_POST['colors']??''))) as $color)db()->prepare('INSERT INTO product_colors(product_id,color_name) VALUES(?,?)')->execute([$id,mb_substr($color,0,60)]);if($path=upload_image($_FILES['image']??[]))db()->prepare('INSERT INTO product_images(product_id,image_path) VALUES(?,?)')->execute([$id,$path]);flash('success','Product updated.');header('Location: manage-products.php');exit;}catch(Throwable $e){flash('error',$e->getMessage());}}?><div class="admin-title"><p>CATALOGUE</p><h2>Edit <?=e($product['name'])?></h2></div><?php require 'product-form.php'; require 'footer.php'; ?>
